function getVariable(name) {
  const {source} = this;
  let obj = {status: 0, word: 0, sort: 0};
  try {
    obj = JSON.parse(source.getVariable());
  } catch(e) {
    source.setVariable(JSON.stringify(obj));
  }
  if (!name) return obj;
  return obj[name];
}

